from dataclasses import dataclass
@dataclass(frozen=True)
class AgentDefinition:name:str;purpose:str;tools:tuple[str,...]
AGENTS={x.name:x for x in [
 AgentDefinition('research','Plan, retrieve, rank, verify, synthesize, cite.',('web_search','rag')),AgentDefinition('syllabus','Map topics to supplied syllabus.',('rag',)),AgentDefinition('notes','Generate structured notes.',('rag',)),AgentDefinition('concept','Explain models and relationships.',('rag',)),AgentDefinition('definition','Create precise definitions.',('rag',)),AgentDefinition('formula','Validate formulas, symbols, and units.',('rag','calculator')),AgentDefinition('derivation','Preserve mathematical transformations.',('rag','symbolic_check')),AgentDefinition('numerical','Solve and verify numerical work.',('calculator','unit_check')),AgentDefinition('question','Create balanced assessments.',('rag',)),AgentDefinition('pyq','Analyze only imported previous-year questions.',('rag','statistics')),AgentDefinition('exam','Analyze syllabus, frequency, marks, difficulty.',('rag','statistics')),AgentDefinition('prediction','Produce uncertain evidence-based priorities.',('rag','statistics')),AgentDefinition('quiz','Generate and score quizzes.',('rag',)),AgentDefinition('memory','Create accurate recall cues.',('rag',)),AgentDefinition('tutor','Teach using selected context.',('rag','memory')),AgentDefinition('voice','Transcribe and answer voice questions.',('stt','tts','rag')),AgentDefinition('youtube','Process legitimate transcript content.',('youtube_transcript','rag')),AgentDefinition('translation','Translate without changing meaning.',('rag',)),AgentDefinition('study_plan','Schedule learning, practice, testing, revision.',('calendar','progress')),AgentDefinition('revision','Prioritize weak and due topics.',('progress','spaced_repetition')),AgentDefinition('fact_check','Check claims against evidence.',('rag','web_search'))]}
def select_agents(mode:str)->list[AgentDefinition]:
 names={'quick_notes':['notes','fact_check'],'detailed_notes':['notes','concept','formula','fact_check'],'deep_research':['research','fact_check'],'exam_mode':['exam','question','revision','fact_check'],'study_everything':['syllabus','notes','concept','definition','formula','derivation','numerical','question','pyq','exam','quiz','memory','revision','fact_check']}[mode]
 return [AGENTS[n] for n in names]
